{
 "contract_type": "msa",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Copperline Software GmbH"],
   "quote": "(1) Northwind Labs, Inc. (\"Northwind\"); and\n(2) Copperline Software GmbH (\"Copperline\")."
  },
  "counterparty": {
   "value": "Copperline Software GmbH",
   "quote": "(2) Copperline Software GmbH (\"Copperline\")."
  },
  "effective_date": {
   "value": "2025-01-26",
   "quote": "Effective Date: 26 January 2025"
  },
  "term_months": {
   "value": 18,
   "quote": "The first term is eighteen (18) months (the \"Initial Term\")."
  },
  "auto_renewal": {
   "value": false,
   "quote": "The Parties can only extend it if they both agree in writing."
  },
  "renewal_notice_days": {
   "value": null,
   "quote": null
  },
  "governing_law": {
   "value": "Texas",
   "quote": "The laws of the State of Texas govern this agreement."
  },
  "liability_cap": {
   "value": null,
   "quote": null
  },
  "payment_terms_days": {
   "value": 45,
   "quote": "Invoices are payable forty-five days after the invoice date."
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": true,
   "quote": "Northwind can end this agreement at any time and for any reason. It must give sixty days' written notice."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Tobias Brandt",
   "email": "tobias.brandt@copperline.example",
   "title": "Geschäftsführer",
   "party": "Copperline Software GmbH"
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "no_liability_cap",
   "severity": "high",
   "message": "The agreement has no limitation of liability clause, so Northwind's exposure (and Copperline's) is uncapped and no damages exclusions apply.",
   "quote": "Neither Party is liable for a delay caused by events beyond its reasonable control."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "high",
   "message": "There is no confidentiality or IP ownership clause, leaving Northwind's confidential information and work product unprotected.",
   "quote": "This agreement is the entire agreement between the Parties. It replaces all earlier discussions about its subject matter."
  },
  {
   "id": "initial_term_expired",
   "severity": "medium",
   "message": "The 18-month Initial Term from 26 January 2025 ended around July 2026 and extension requires written agreement, so services may now be outside the contract.",
   "quote": "The Parties can only extend it if they both agree in writing."
  },
  {
   "id": "exclusive_texas_courts",
   "severity": "low",
   "message": "Disputes must be brought only in Texas courts, which may be inconvenient or costly for a German counterparty and limits forum flexibility.",
   "quote": "Any dispute must be resolved only in the courts located in Texas."
  },
  {
   "id": "non_solicit_survives",
   "severity": "low",
   "message": "A mutual non-solicitation of Personnel binds Northwind for the term plus twelve months.",
   "quote": "This applies during the term of this agreement and for twelve months afterwards."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a Master Services Agreement between Northwind Labs, Inc. and Copperline Software GmbH, effective 26 January 2025, with an 18-month initial term that can only be extended by written agreement. Northwind may terminate for convenience on sixty days' notice, invoices are due in 45 days, Texas law applies, and there is no liability cap or confidentiality clause."
}
